194	    /// Creates a new loader given the configuration.
195	    pub fn new(
196	        input: Option<&Input>,
197	        world_args: &'static WorldArgs,
198	    ) -> Result<Self, WorldCreationError> {
199	        // Resolve the system-global input path.
200	        let input_path = match input {
201	            Some(Input::Path(path)) => {
202	                Some(path.canonicalize().map_err(|err| match err.kind() {
203	                    io::ErrorKind::NotFound => {
204	                        WorldCreationError::InputNotFound(path.clone())
205	                    }
206	                    _ => WorldCreationError::Io(err),
207	                })?)
208	            }
209	            _ => None,
210	        };
211	
212	        // Resolve the system-global root directory.
213	        let root = {
214	            let path = world_args
215	                .root
216	                .as_deref()
217	                .or_else(|| input_path.as_deref()?.parent())
218	                .unwrap_or(Path::new("."));
219	            path.canonicalize().map_err(|err| match err.kind() {
220	                io::ErrorKind::NotFound => {
221	                    WorldCreationError::RootNotFound(path.to_path_buf())
222	                }
223	                _ => WorldCreationError::Io(err),
224	            })?
225	        };
226	
227	        let main = if let Some(path) = &input_path {
228	            // Resolve the virtual path of the main file within the project root.
229	            RootedPath::new(VirtualRoot::Project, VirtualPath::virtualize(&root, path)?)
230	                .intern()
231	        } else if matches!(input, Some(Input::Stdin)) {
232	            // Return the special id of STDIN.
233	            *STDIN_ID
234	        } else {
235	            // Return the special id of EMPTY/no input at all otherwise.
236	            *EMPTY_ID
237	        };
238	
239	        Ok(Self {
240	            main,
241	            project: FsRoot::new(root),
242	            packages: crate::packages::system(&world_args.package),
243	        })
244	    }
