246	    /// Resolves the file system path for the given `id`.
247	    pub fn resolve(&self, id: FileId) -> FileResult<PathBuf> {
248	        self.root(id)?.resolve(id.vpath())
249	    }
250	
251	    /// Resolves the root in which the given file ID resides.
252	    fn root(&self, id: FileId) -> FileResult<FsRoot> {
253	        Ok(match id.root() {
254	            VirtualRoot::Project => self.project.clone(),
255	            VirtualRoot::Package(spec) => self.packages.obtain(spec)?,
256	        })
257	    }
258	}
