272	/// Read from stdin.
273	fn read_from_stdin() -> FileResult<Vec<u8>> {
274	    let mut buf = Vec::new();
275	    let result = io::stdin().read_to_end(&mut buf);
276	    match result {
277	        Ok(_) => (),
278	        Err(err) if err.kind() == io::ErrorKind::BrokenPipe => (),
279	        Err(err) => return Err(FileError::from_io(err, Path::new("<stdin>"))),
280	    }
281	    Ok(buf)
282	}
