284	/// An error that occurs during world construction.
285	#[derive(Debug)]
286	pub enum WorldCreationError {
287	    /// The input file does not appear to exist.
288	    InputNotFound(PathBuf),
289	    /// The input file path was malformed.
290	    InputMalformed(VirtualizeError),
291	    /// The root directory does not appear to exist.
292	    RootNotFound(PathBuf),
293	    /// The requested creation timestamp was invalid.
294	    InvalidTimestamp,
295	    /// Another type of I/O error.
296	    Io(io::Error),
297	}
