299	impl fmt::Display for WorldCreationError {
300	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
301	        match self {
302	            WorldCreationError::InputMalformed(err) => match err {
303	                VirtualizeError::Path(PathError::Escapes) => {
304	                    write!(f, "source file must be contained in project root")
305	                }
306	                VirtualizeError::Path(PathError::Backslash) => {
307	                    write!(f, "source path must not contain a backslash")
308	                }
309	                VirtualizeError::Invalid(s) => {
310	                    write!(f, "source path contains invalid sequence `{}`", s.repr())
311	                }
312	                VirtualizeError::Utf8 => write!(f, "source path must be valid UTF-8"),
313	            },
314	            WorldCreationError::InputNotFound(path) => {
315	                write!(f, "input file not found (searched at {})", path.display())
316	            }
317	            WorldCreationError::RootNotFound(path) => {
318	                write!(f, "root directory not found (searched at {})", path.display())
319	            }
320	            WorldCreationError::InvalidTimestamp => {
321	                write!(f, "creation timestamp out of range")
322	            }
323	            WorldCreationError::Io(err) => write!(f, "{err}"),
324	        }
325	    }
326	}
327	
328	impl error::Error for WorldCreationError {
329	    fn source(&self) -> Option<&(dyn error::Error + 'static)> {
330	        match self {
331	            Self::Io(error) => Some(error),
332	            _ => None,
333	        }
334	    }
335	}
